validate_doc_update:
function(newDoc, oldDoc, userCtx, secObj) {
  // Admin can do anything
  if (userCtx.roles.indexOf('admin') !== -1 || userCtx.roles.indexOf('_admin') !== -1) return;

  // Users can only edit their own user doc
  if (newDoc._id.indexOf('org.couchdb.user:') === 0) {
    var docUser = newDoc._id.replace('org.couchdb.user:', '');
    if (userCtx.name !== docUser) {
      throw({forbidden: 'You can only edit your own user document'});
    }
    // Non-admins cannot change roles
    if (oldDoc && JSON.stringify(newDoc.roles) !== JSON.stringify(oldDoc.roles)) {
      throw({forbidden: 'Only admins can change roles'});
    }
    return;
  }

  // Domain docs — admin only
  if (newDoc._id.indexOf('alias-') !== 0 && newDoc._id.indexOf('invite-') !== 0 && newDoc._id.indexOf('org.couchdb.user:') !== 0 && newDoc._id.indexOf('_design/') !== 0) {
    throw({forbidden: 'Only admins can modify domain documents'});
  }

  // Alias docs — admin only
  if (newDoc._id.indexOf('alias-') === 0) {
    throw({forbidden: 'Only admins can modify aliases'});
  }

  // Invite consumption — verify token is valid
  if (newDoc._id.indexOf('invite-') === 0) {
    throw({forbidden: 'Only admins can modify invite documents'});
  }
}
